package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.*;import com.hmdp.ai.runtime.tool.skill.dto.ShopAnalysisData;import org.springframework.stereotype.Component;
@Component @AgentSkill(code="get-shop-detailed-analysis") public class GetShopDetailedAnalysisSkill extends ShopSkillSupport implements LocalSkill {public GetShopDetailedAnalysisSkill(ShopDataPort s,ReviewDataPort r,ObjectMapper m){super(s,r,m);}@Override public JsonNode execute(ExecutionContext c,JsonNode in){long id=shopId(in);int limit=Math.max(1,Math.min(50,in.path("reviewLimit").asInt(10)));return json(new ShopAnalysisData(shops.getShop(id),shops.getReviewCount(id),evidence(reviews.findRecentReviews(id,limit))));}}
